import { screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { renderWithProviders } from "../../../tests/utils";
import { ConversationEventType, type ConversationEvent, type Skill } from "../../../types";
import { SkillEvent } from "./SkillEvent";

const skill: Skill = {
  id: "card_replace",
  name: "Card Replace",
  description: null,
  is_default: false,
  engine_managed: false,
  disabled: false,
  sections: [],
  blocks: {},
  referenced_skills: [],
  tool_names: [],
  hidden: false,
};

function makeEvent(
  eventType: ConversationEventType = ConversationEventType.SkillActivated,
  skillId = "card_replace",
): ConversationEvent {
  return {
    __typename: "ConversationEvent",
    id: "1",
    conversationEventType: eventType,
    skillId,
    name: eventType.toLowerCase(),
    timestamp: new Date().toISOString(),
    originalTimestamp: 0,
    metadata: { parseData: {} },
  };
}

describe("SkillEvent", () => {
  it("renders the catalog display name and lifecycle verb", () => {
    renderWithProviders(<SkillEvent event={makeEvent()} isSelected={false} />, {
      initialStoreState: { skillCatalog: { card_replace: skill } },
    });

    expect(screen.getByText("Card Replace")).toBeInTheDocument();
    expect(screen.getByText(/skill activated/)).toBeInTheDocument();
  });

  it("renders every lifecycle verb", () => {
    const eventTypes = [
      [ConversationEventType.SkillCompleted, "completed"],
      [ConversationEventType.SkillCancelled, "cancelled"],
      [ConversationEventType.SkillInterrupted, "interrupted"],
      [ConversationEventType.SkillResumed, "resumed"],
    ] as const;

    for (const [eventType, verb] of eventTypes) {
      const { unmount } = renderWithProviders(
        <SkillEvent event={makeEvent(eventType)} isSelected={false} />,
        { initialStoreState: { skillCatalog: { card_replace: skill } } },
      );
      expect(screen.getByText(new RegExp(`skill ${verb}`))).toBeInTheDocument();
      unmount();
    }
  });

  it("falls back to the skill id when the catalog has no entry", () => {
    renderWithProviders(
      <SkillEvent
        event={makeEvent(ConversationEventType.SkillActivated, "unknown_skill")}
        isSelected={false}
      />,
      { initialStoreState: { skillCatalog: {} } },
    );

    expect(screen.getByText("unknown_skill")).toBeInTheDocument();
  });
});
